            related_entity_type: 'category', related_entity_id: h.c.categoryId,
            metric_name: 'category_expense', metric_value: h.c.total, comparison_value: Math.round(h.ba * 100) / 100, comparison_percentage: Math.round(h.p * 10) / 10,
