        var invs = DB.listInvoices(userId, {}).filter(function (i) {
          var ref = i.reference_year + '-' + ('0' + i.reference_month).slice(-2);
          return ref >= f.fromYm && ref <= f.toYm && (!f.credit_card_id || i.credit_card_id === f.credit_card_id);
        });
